using static Bootcamp.Check;

Invite Create(TimeProvider clock, string email)
{
    var now = clock.GetUtcNow();
    return new Invite(email, now, now.AddDays(7));
}

int Accept(TimeProvider clock, Invite invite) =>
    clock.GetUtcNow() < invite.ExpiresAt ? 200 : 410;

var T0 = new DateTimeOffset(2026, 3, 1, 9, 0, 0, TimeSpan.Zero);
string Iso(DateTimeOffset t) => t.ToString("O");   // compare instants as ISO-8601 text

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("the manual clock returns its start, and advances add up", () =>
{
    var clock = new ManualClock(T0);
    Eq(Iso(clock.GetUtcNow()), Iso(T0));
    clock.Advance(TimeSpan.FromHours(1));
    clock.Advance(TimeSpan.FromMinutes(30));
    Eq(Iso(clock.GetUtcNow()), Iso(T0.AddMinutes(90)));
});

Test("a negative advance throws", () =>
    Throws<ArgumentOutOfRangeException>(() => new ManualClock(T0).Advance(TimeSpan.FromSeconds(-1))));

Test("Create reads the clock once, so ExpiresAt is exactly 7 days after CreatedAt", () =>
{
    var clock = new TickingClock(T0);
    var invite = Create(clock, "ana@x.io");
    Eq((invite.Email, Iso(invite.CreatedAt), invite.ExpiresAt - invite.CreatedAt, clock.Reads), ("ana@x.io", Iso(T0), TimeSpan.FromDays(7), 1));
});

Test("Create uses the clock it is given, never the system clock", () =>
{
    var past = new DateTimeOffset(2001, 1, 1, 0, 0, 0, TimeSpan.Zero);
    Eq(Iso(Create(new ManualClock(past), "bo@x.io").ExpiresAt), Iso(past.AddDays(7)));
});

Test("one second before expiry the invite is accepted", () =>
{
    var clock = new ManualClock(T0);
    var invite = Create(clock, "ana@x.io");
    clock.Advance(TimeSpan.FromDays(7) - TimeSpan.FromSeconds(1));
    Eq(Accept(clock, invite), 200);
});

Test("at the expiry instant the invite is gone (boundary)", () =>
{
    var clock = new ManualClock(T0);
    var invite = Create(clock, "ana@x.io");
    clock.Advance(TimeSpan.FromDays(7));
    Eq(Accept(clock, invite), 410);
});

