// ──────────────────────────── types ──────────────────────────────────────

record Invite(string Email, DateTimeOffset CreatedAt, DateTimeOffset ExpiresAt);

/// <summary>A clock the test sets and moves forward.</summary>
sealed class ManualClock : TimeProvider
{
    DateTimeOffset now;

    public ManualClock(DateTimeOffset start) => now = start;

    public override DateTimeOffset GetUtcNow() => now;

    public void Advance(TimeSpan by)
    {
        if (by < TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(by), "the clock does not run backwards");
        now += by;
    }
}

/// <summary>Given: moves 1 ms forward on every read and counts the reads.</summary>
sealed class TickingClock(DateTimeOffset start) : TimeProvider
{
    DateTimeOffset now = start;
    public int Reads { get; private set; }
    public override DateTimeOffset GetUtcNow()
    {
        Reads++;
        var t = now;
        now = now.AddMilliseconds(1);
        return t;
    }
}

drills.explanation:
The clock is just another dependency. The fake keeps one instant and moves it only when told:

```csharp
public override DateTimeOffset GetUtcNow() => now;
public void Advance(TimeSpan by)
{
    if (by < TimeSpan.Zero) throw new ArgumentOutOfRangeException(nameof(by));
    now += by;
}
```

The service reads it once and compares with `<`:

```csharp
var now = clock.GetUtcNow();
return new Invite(email, now, now.AddDays(7));
// Accept:
clock.GetUtcNow() < invite.ExpiresAt ? 200 : 410;
```

The tests catch three plausible wrong versions: two reads of the clock (the ticking clock makes `ExpiresAt - CreatedAt` one millisecond too long), `DateTimeOffset.UtcNow` anywhere (the 2001 clock is ignored), and `<=` in `Accept` (the invite is still accepted at the exact expiry instant).

