// ──────────────────────────── tests ──────────────────────────────────────

Test("users get ids 1, 2, 3 in order", () =>
{
    var store = new InMemoryUserStore();
    Eq(new[] { store.Add("ana@x.io", "Ana").Id, store.Add("bo@x.io", "Bo").Id, store.Add("cy@x.io", "Cy").Id }, new[] { 1, 2, 3 });
});

Test("signup answers 201 and then 409 for the same email in another case", () =>
{
    var store = new InMemoryUserStore();
    Eq(Signup(store, "Ana@x.io", "Ana"), (201, (int?)1));
    Eq(Signup(store, "ana@X.IO", "Other"), (409, (int?)null));
});

Test("a refused add stores nothing", () =>
{
    var store = new InMemoryUserStore();
    store.Add("ana@x.io", "Ana");
    Throws<DuplicateEmailException>(() => store.Add("ANA@x.io", "Other"));
    Eq(store.All().Select(u => (u.Id, u.Email, u.Name)), new[] { (1, "ana@x.io", "Ana") });
});

Test("Find hands out a copy: changing it does not change the store", () =>
{
    var store = new InMemoryUserStore();
    store.Add("ana@x.io", "Ana");
    var user = store.Find(1)!;
    user.Name = "Changed in the test";
    Eq(store.Find(1)!.Name, "Ana");
});

Test("All hands out copies in id order", () =>
{
    var store = new InMemoryUserStore();
    store.Add("bo@x.io", "Bo");
    store.Add("ana@x.io", "Ana");
    var all = store.All();
    all[0].Name = "Changed";
    Eq(store.All().Select(u => (u.Id, u.Name)), new[] { (1, "Bo"), (2, "Ana") });
});

Test("Find of an unknown id is null (boundary)", () =>
    Eq(new InMemoryUserStore().Find(1), null));

