// ──────────────────────────── types ──────────────────────────────────────

sealed class User(int id, string email, string name)
{
    public int Id { get; } = id;
    public string Email { get; } = email;
    public string Name { get; set; } = name;
}

sealed class DuplicateEmailException(string email) : Exception($"duplicate key value violates unique index on Email: {email}");

interface IUserStore
{
    User Add(string email, string name);
    User? Find(int id);
    IReadOnlyList<User> All();
}

sealed class InMemoryUserStore : IUserStore
{
    readonly List<User> rows = new();

    static User Copy(User u) => new(u.Id, u.Email, u.Name);

    public User Add(string email, string name)
    {
        if (rows.Any(u => string.Equals(u.Email, email, StringComparison.OrdinalIgnoreCase)))
            throw new DuplicateEmailException(email);
        var user = new User(rows.Count + 1, email, name);
        rows.Add(user);
        return Copy(user);
    }

    public User? Find(int id) => rows.FirstOrDefault(u => u.Id == id) is { } u ? Copy(u) : null;

    public IReadOnlyList<User> All() => rows.OrderBy(u => u.Id).Select(Copy).ToList();
}

drills.explanation:
Keep the rows private, check the unique rule before storing, and copy on the way out:

```csharp
if (rows.Any(u => string.Equals(u.Email, email, StringComparison.OrdinalIgnoreCase)))
    throw new DuplicateEmailException(email);
var user = new User(rows.Count + 1, email, name);
rows.Add(user);
return Copy(user);
```

`Find` and `All` return `new User(u.Id, u.Email, u.Name)` for each row, the way every database read builds fresh objects.

The tests catch the two fakes that make suites lie: a `Dictionary<string, User>` keyed by the raw email (the case-only duplicate gets 201, so the 409 path is never tested), and a fake that returns its stored objects (a test that edits a returned user silently changes the "database", so a missing save goes unnoticed).
